// ─── Simule la détection de signaux (en prod : scraper LinkedIn) ──
// En production, ce nœud appelle un service de veille
// (ex: Phantombuster, Apify, ou RSS d'alertes Google News).
// Ici : simulation avec données réalistes.

const prospects = $input.all().map(i => i.json);

const SIGNAL_TEMPLATES = [
  { type: 'company_funding',   strength: 'critical', delta: 4, title: 'Levée de fonds Series A', excerpt: 'a annoncé une levée de fonds de {amount}M€' },
  { type: 'job_change',        strength: 'high',     delta: 3, title: 'Nouveau poste', excerpt: 'vient de rejoindre {company} en tant que {title}' },
  { type: 'viral_post',        strength: 'medium',   delta: 2, title: 'Publication virale LinkedIn', excerpt: 'a publié un contenu qui génère plus de {likes} réactions sur LinkedIn' },
  { type: 'buying_signal',     strength: 'critical', delta: 5, title: 'Signal d\'achat détecté', excerpt: 'cherche activement une solution pour {pain_point}' },
  { type: 'company_expansion', strength: 'high',     delta: 3, title: 'Expansion en cours', excerpt: 'recrute massivement : {count} postes ouverts cette semaine' },
  { type: 'pain_point_signal', strength: 'high',     delta: 3, title: 'Pain point exprimé publiquement', excerpt: 'a exprimé une frustration sur {topic} qui correspond à notre proposition de valeur' }
];

// En prod : parcourir les prospects et appeler l'API de veille
// Ici : sélectionner aléatoirement 20-30% des prospects avec un signal simulé
const withSignals = prospects
  .filter(() => Math.random() < 0.25)  // ~25% ont un signal
  .map(p => {
    const tpl = SIGNAL_TEMPLATES[Math.floor(Math.random() * SIGNAL_TEMPLATES.length)];
    return {
      json: {
        ...p,
        _signal: {
          type: tpl.type,
          strength: tpl.strength,
          delta: tpl.delta,
          title: tpl.title,
          excerpt: tpl.excerpt.replace('{amount}', Math.floor(Math.random()*10)+2)
                              .replace('{company}', p.company || 'nouvelle entreprise')
                              .replace('{title}', p.title || 'directeur')
                              .replace('{likes}', Math.floor(Math.random()*2000)+500)
                              .replace('{pain_point}', 'la gestion de leur prospection')
                              .replace('{count}', Math.floor(Math.random()*8)+3)
                              .replace('{topic}', 'la productivité commerciale'),
          source: 'linkedin_activity',
          signal_date: new Date(Date.now() - Math.random() * 2 * 24 * 3600 * 1000).toISOString().split('T')[0]
        }
      }
    };
  });

console.log(`[WF9] ${withSignals.length} signaux détectés sur ${prospects.length} prospects surveillés`);
return withSignals;

