// ─── Alerte Discord pour signal critique ─────────────────────────
const d = $('Prépare sauvegarde signal').item.json;
const typeEmoji = {
  company_funding: '💰',
  buying_signal: '🎯',
  job_change: '🔄',
  company_expansion: '📈',
  viral_post: '🔥',
  pain_point_signal: '⚡'
};

return [{
  json: {
    embeds: [{
      title: `${typeEmoji[d.signal_type] || '📡'} Signal ${d.signal_strength.toUpperCase()} détecté !`,
      description: `**${d.full_name}** vient de déclencher un signal d'opportunité.`,
      color: 15844367,
      fields: [
        { name: '📡 Signal', value: d.signal_title, inline: true },
        { name: '📈 Score', value: `+${d.score_delta} pts → ${d.new_score}/10`, inline: true },
        { name: '💬 Message généré', value: d.generated_message || '_En génération…_', inline: false },
        { name: '✅ Action recommandée', value: d.signal_strength === 'critical' ? 'Envoyer manuellement maintenant' : 'Intégré dans la prochaine relance auto', inline: false }
      ],
      footer: { text: `Signal Detection WF9 • ${new Date().toLocaleDateString('fr-FR')}` },
      timestamp: new Date().toISOString()
    }]
  }
}];

// ─── Shadow ban detection ────────────────────────────────────────
// Calcule le taux d'acceptation des 24 dernières heures
// et compare à la moyenne des 7 derniers jours.

const prospects = $('Fetch prospects à surveiller (DB)').all().map(i => i.json);

// En prod : requête DB sur actions recent vs historique
// Simulation ici
const platforms = ['linkedin', 'instagram'];

return platforms.map(platform => {
  const recentRate = 15 + Math.random() * 30;  // Taux simulé
  const avgRate7d = 22 + Math.random() * 10;
  const drop = avgRate7d > 0 ? ((avgRate7d - recentRate) / avgRate7d * 100) : 0;

  const healthScore = Math.max(0, Math.min(100,
    100 - (drop > 30 ? 40 : drop > 15 ? 20 : 0)
  ));

  return {
    json: {
      platform,
      recent_rate: parseFloat(recentRate.toFixed(1)),
      avg_rate_7d: parseFloat(avgRate7d.toFixed(1)),
      drop_pct: parseFloat(drop.toFixed(1)),
      health_score: healthScore,
      health_status: healthScore < 60 ? 'degraded' : healthScore < 80 ? 'warning' : 'healthy',
      rate_drop_flag: drop >= 30,
      should_alert: drop >= 30
    }
  };
});
